func TestParseMarkets() {
	exchange := ccxt.NewExchange().(*ccxt.Exchange)
	exchange.DerivedExchange = exchange
	exchange.InitParent(map[string]any{
		"id": "sampleex",
	}, map[string]any{}, exchange)
	// we don't check empty base or quote inside parseMarkets
	var markets []any = []any{map[string]any{
		"id":    "BTC_USD",
		"base":  "BTC",
		"quote": "USD",
	}, map[string]any{
		"id":    nil,
		"base":  "ETH",
		"quote": "USD",
	}, map[string]any{
		"id":    "ETH_USD",
		"base":  nil,
		"quote": "USD",
	}, map[string]any{
		"id":    "ETH_USD",
		"base":  "ETH",
		"quote": nil,
	}}
	var parsedMarkets any = exchange.ParseMarkets(markets)
	assert((ccxt.IsEqual(ccxt.GetArrayLength(parsedMarkets), 2)), "Expected 3 parsed markets")
	assert(!ccxt.IsEqual(ccxt.GetValue(parsedMarkets, 0), nil) && (ccxt.IsEqual(ccxt.GetValue(ccxt.GetValue(parsedMarkets, 0), "base"), "BTC")), "Expected BTC as base for the first market")
}
